package com.example.networkservice.model; import org.springframework.data.annotation.Id; import org.springframework.data.mongodb.core.mapping.Document; import java.time.Instant; @Document("activations") public class Activation{@Id private String id;private String orderId,customerId,planId,iccid;private ActivationStatus status;private Instant requestedAt,readyAt,activatedAt;public String getId(){return id;}public String getOrderId(){return orderId;}public void setOrderId(String v){orderId=v;}public String getCustomerId(){return customerId;}public void setCustomerId(String v){customerId=v;}public String getPlanId(){return planId;}public void setPlanId(String v){planId=v;}public String getIccid(){return iccid;}public void setIccid(String v){iccid=v;}public ActivationStatus getStatus(){return status;}public void setStatus(ActivationStatus v){status=v;}public Instant getRequestedAt(){return requestedAt;}public void setRequestedAt(Instant v){requestedAt=v;}public Instant getReadyAt(){return readyAt;}public void setReadyAt(Instant v){readyAt=v;}public Instant getActivatedAt(){return activatedAt;}public void setActivatedAt(Instant v){activatedAt=v;}}
